export interface WikiLink {
  target: string;
  heading: string | null;
  alias: string | null;
}

export interface NoteInput {
  id: string;
  title: string;
  body: string;
}

export interface GraphNode {
  id: string;
  title: string;
  degree: number;
}

export interface GraphEdge {
  from: string;
  to: string;
}

export interface GraphResult {
  nodes: GraphNode[];
  edges: GraphEdge[];
  backlinks: Record<string, string[]>;
  unresolved: Record<string, string[]>;
}

export declare function parseWikiLinks(markdown: string): WikiLink[];
export declare function normalizeTitle(title: string): string;
export declare function buildLinkGraph(notes: NoteInput[]): GraphResult;

