test("REQ-1: parses wikilinks while ignoring code spans", () => {
  const links = parseWikiLinks("Read [[Architecture]] or `[[Ignored]]`");
  assert.equal(links.length, 1);
  assert.equal(links[0].target, "Architecture");
});

test("REQ-2: normalizes titles with whitespace collapsing", () => {
  assert.equal(normalizeTitle("  My   Note  "), "my note");
});

test("REQ-3 REQ-4 REQ-5: constructs graph with edges, backlinks, and degree", () => {
  const notes = [
    { id: "1", title: "Index", body: "Links to [[Guide]] and [[Missing]]" },
    { id: "2", title: "Guide", body: "Self link [[Guide]] and back [[Index]]" },
  ];
  const g = buildLinkGraph(notes);
  assert.equal(g.edges.length, 2);
  assert.deepEqual(g.backlinks["2"], ["1"]);
  assert.deepEqual(g.unresolved["1"], ["Missing"]);
});

